{
  "template": {
    "format_id": "amvision.workflow-graph-template.v1",
    "template_id": "opencv-process-save-image-zeromq-template",
    "template_version": "1.0.0",
    "display_name": "OpenCV Process Save Image ZeroMQ Template",
    "description": "同时接收 HTTP image-base64 和 TriggerSource image-ref 图片；ZeroMQ image-ref 直接进入 image-ref 合流节点，base64 仅作为调试 fallback，OpenCV 节点默认保持 image-ref 高性能流转。",
    "nodes": [
      {
        "node_id": "resolve_request_image",
        "node_type_id": "core.logic.image-ref-coalesce",
        "parameters": {}
      },
      {
        "node_id": "decode_request_image",
        "node_type_id": "core.io.image-base64-decode",
        "parameters": {}
      },
      {
        "node_id": "blur_image",
        "node_type_id": "custom.opencv.gaussian-blur",
        "parameters": {
          "kernel_size": 5,
          "sigma_x": 1.2
        }
      },
      {
        "node_id": "threshold_image",
        "node_type_id": "custom.opencv.binary-threshold",
        "parameters": {
          "threshold": 96,
          "max_value": 255
        }
      },
      {
        "node_id": "edge_image",
        "node_type_id": "custom.opencv.canny",
        "parameters": {
          "threshold1": 60,
          "threshold2": 160,
          "aperture_size": 3,
          "l2_gradient": false
        }
      },
      {
        "node_id": "save_image",
        "node_type_id": "core.io.image-save",
        "parameters": {
          "save_directory": "{workflow_app_result_dir}",
          "file_name": "{node_id}-{YYYYMMDDhhmmssSSS}.png",
          "overwrite": false
        }
      },
      {
        "node_id": "preview_image",
        "node_type_id": "core.output.image-body",
        "parameters": {
          "title": "Saved Edge Image",
          "response_transport_mode": "storage-ref"
        }
      },
      {
        "node_id": "response",
        "node_type_id": "core.output.http-response",
        "parameters": {
          "status_code": 200
        }
      }
    ],
    "edges": [
      {
        "edge_id": "edge-decode-request-image-fallback",
        "source_node_id": "decode_request_image",
        "source_port": "image",
        "target_node_id": "resolve_request_image",
        "target_port": "fallback"
      },
      {
        "edge_id": "edge-input-blur",
        "source_node_id": "resolve_request_image",
        "source_port": "image",
        "target_node_id": "blur_image",
        "target_port": "image"
      },
      {
        "edge_id": "edge-blur-threshold",
        "source_node_id": "blur_image",
        "source_port": "image",
        "target_node_id": "threshold_image",
        "target_port": "image"
      },
      {
        "edge_id": "edge-threshold-canny",
        "source_node_id": "threshold_image",
        "source_port": "image",
        "target_node_id": "edge_image",
        "target_port": "image"
      },
      {
        "edge_id": "edge-canny-save",
        "source_node_id": "edge_image",
        "source_port": "image",
        "target_node_id": "save_image",
        "target_port": "image"
      },
      {
        "edge_id": "edge-save-preview",
        "source_node_id": "save_image",
        "source_port": "image",
        "target_node_id": "preview_image",
        "target_port": "image"
      },
      {
        "edge_id": "edge-preview-response",
        "source_node_id": "preview_image",
        "source_port": "body",
        "target_node_id": "response",
        "target_port": "body"
      }
    ],
    "template_inputs": [
      {
        "input_id": "request_image_base64",
        "display_name": "Request Image Base64",
        "payload_type_id": "image-base64.v1",
        "target_node_id": "decode_request_image",
        "target_port": "payload",
        "required": false
      },
      {
        "input_id": "request_image_ref",
        "display_name": "Request Image Ref",
        "payload_type_id": "image-ref.v1",
        "target_node_id": "resolve_request_image",
        "target_port": "primary",
        "required": false
      }
    ],
    "template_outputs": [
      {
        "output_id": "http_response",
        "display_name": "HTTP Response",
        "payload_type_id": "http-response.v1",
        "source_node_id": "response",
        "source_port": "response"
      }
    ],
    "metadata": {
      "example_kind": "opencv-process-save-image-zeromq",
      "node_groups": {
        "input": [
          "resolve_request_image",
          "decode_request_image"
        ],
        "opencv_process": [
          "blur_image",
          "threshold_image",
          "edge_image"
        ],
        "output": [
          "save_image",
          "preview_image",
          "response"
        ]
      },
      "trigger_source_input": "zeromq",
      "http_input_binding": "request_image_base64",
      "trigger_source_input_binding": "request_image_ref"
    }
  }
}

{
  "application": {
    "format_id": "amvision.flow-application.v1",
    "application_id": "opencv-process-save-image-zeromq-app",
    "display_name": "OpenCV Process Save Image ZeroMQ App",
    "description": "同一个 workflow app 同时接收 HTTP image-base64 和 TriggerSource image-ref；ZeroMQ image-ref 直接进入 image-ref 合流节点，HTTP/base64 只作为调试 fallback。",
    "template_ref": {
      "template_id": "opencv-process-save-image-zeromq-template",
      "template_version": "1.0.0",
      "source_kind": "json-file",
      "source_uri": "docs/examples/workflows/opencv_process_save_image_zeromq.template.json"
    },
    "bindings": [
      {
        "binding_id": "request_image_base64",
        "direction": "input",
        "template_port_id": "request_image_base64",
        "binding_kind": "api-request",
        "required": false,
        "config": {
          "route": "/api/v1/workflow-apps/opencv/process-save-image-dual-input",
          "method": "POST"
        },
        "metadata": {
          "payload_type_id": "image-base64.v1",
          "trigger_kind": "http-api"
        }
      },
      {
        "binding_id": "request_image_ref",
        "direction": "input",
        "template_port_id": "request_image_ref",
        "binding_kind": "trigger-source-input",
        "required": false,
        "config": {
          "payload_type_id": "image-ref.v1",
          "content_type": "application/json"
        },
        "metadata": {
          "payload_type_id": "image-ref.v1",
          "trigger_kind": "zeromq-topic"
        }
      },
      {
        "binding_id": "http_response",
        "direction": "output",
        "template_port_id": "http_response",
        "binding_kind": "http-response",
        "config": {
          "status_code": 200
        },
        "metadata": {
          "payload_type_id": "http-response.v1"
        }
      }
    ],
    "runtime_mode": "python-json-workflow",
    "metadata": {
      "example_kind": "opencv-process-save-image-zeromq",
      "intended_saved_object_key": "workflows/projects/{project_id}/applications/opencv-process-save-image-zeromq-app/application.json",
      "trigger_source_input": "zeromq",
      "http_input_binding": "request_image_base64",
      "trigger_source_input_binding": "request_image_ref"
    }
  }
}

{
  "trigger_source_id": "zeromq-trigger-source-07",
  "project_id": "project-1",
  "display_name": "ZeroMQ TriggerSource 07 OpenCV Process Save Image",
  "trigger_kind": "zeromq-topic",
  "workflow_runtime_id": "{{workflowRuntimeId}}",
  "submit_mode": "sync",
  "enabled": false,
  "transport_config": {
    "bind_endpoint": "tcp://127.0.0.1:5556",
    "default_input_binding": "request_image_ref",
    "content_transport": "local-buffer"
  },
  "input_binding_mapping": {
    "request_image_ref": {
      "source": "payload.request_image_ref",
      "required": false,
      "payload_type_id": "image-ref.v1"
    }
  },
  "result_mapping": {
    "result_bindings": [
      "http_response"
    ]
  },
  "default_execution_metadata": {
    "scenario": "opencv-process-save-image-zeromq",
    "trigger_source": "zeromq-sdk",
    "trace_level": "none",
    "retain_trace_enabled": false,
    "retain_node_records_enabled": false
  },
  "ack_policy": "ack-after-run-finished",
  "result_mode": "sync-reply",
  "reply_timeout_seconds": 30,
  "idempotency_key_path": "payload.idempotency_key",
  "metadata": {
    "example_kind": "opencv-process-save-image-zeromq",
    "sdk": "dotnet"
  }
}
